messages.content:
Berikut manifest game "Kebutuhan Run" — Endless Runner edukasi ekonomi dengan tema Clean Modern dan kesulitan Normal.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "kebutuhan-run", title: "Kebutuhan Run", seed: "kebutuhan-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ekonomi",
    concept: "Penggolongan kebutuhan primer, sekunder, dan tersier",
    objectives: ["Mengelompokkan kebutuhan berdasarkan tingkat kepentingannya"],
    misconceptions: ["Semua benda mahal otomatis termasuk kebutuhan tersier"],
    mode: "category",
    categories: [
      { id: "primer",   label: "Primer",   color: "#2F80ED" },
      { id: "sekunder", label: "Sekunder", color: "#3FA34D" },
      { id: "tersier",  label: "Tersier",  color: "#E5484D" }
    ],
    items: [
      { id: "beras",        label: "Beras",             category: "primer",   explain: "Makanan pokok sehari-hari yang wajib dipenuhi." },
      { id: "air-minum",    label: "Air minum",         category: "primer",   explain: "Kebutuhan dasar tubuh yang tidak bisa ditunda." },
      { id: "pakaian",      label: "Pakaian sehari-hari", category: "primer", explain: "Melindungi tubuh; kebutuhan dasar sandang." },
      { id: "obat",         label: "Obat saat sakit",   category: "primer",   explain: "Kebutuhan mendesak untuk kesehatan; mahal bukan berarti tersier." },
      { id: "sepeda-motor", label: "Sepeda motor",      category: "sekunder", explain: "Alat transportasi penunjang aktivitas, bukan kebutuhan pokok." },
      { id: "ponsel",       label: "Telepon seluler",   category: "sekunder", explain: "Alat komunikasi yang menambah kenyamanan." },
      { id: "kulkas",       label: "Kulkas",            category: "sekunder", explain: "Membantu menyimpan makanan; pelengkap, bukan pokok." },
      { id: "kipas",        label: "Kipas angin",       category: "sekunder", explain: "Memberi kenyamanan, bukan kebutuhan dasar." },
      { id: "perhiasan",    label: "Perhiasan emas",    category: "tersier",  explain: "Barang mewah untuk prestise, bukan kebutuhan pokok." },
      { id: "mobil-mewah",  label: "Mobil mewah",       category: "tersier",  explain: "Kendaraan mewah untuk gengsi, bukan kebutuhan dasar." },
      { id: "liburan",      label: "Liburan luar negeri", category: "tersier", explain: "Rekreasi mewah, bukan kebutuhan dasar." },
      { id: "jam-desainer", label: "Jam tangan desainer", category: "tersier", explain: "Aksesori prestise bernilai tinggi." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain memilah kebutuhan primer, sekunder, dan tersier lewat item yang diambil sesuai target. Asumsi penting: item "Obat saat sakit" sengaja dimasukkan sebagai jebakan miskonsepsi "mahal = tersier", karena obat tetap kebutuhan primer saat dibutuhkan.
